/* From Uiverse.io by Cobp  - Tags: material design, animation, 3d, card, modern */
.__UIV_SCOPE__ .card {
  position: relative;
  display: flex;
  flex-direction: column;
  background-color: #242824;
  padding: 10px;
  border-radius: 6px;
  gap: 0.5rem;
  height: max-content;
}
.__UIV_SCOPE__ .card_form {
  position: relative;
  width: 15em;
  height: 15em;
  border-radius: 4px;
  background-color: #9147ff;
  transition: 0.2s ease-in-out;
  overflow: hidden;
}
.__UIV_SCOPE__ .card_form span {
  font-size: 1.5em;
  position: absolute;
  inset: 0;
  padding: 5px 10px;
  color: #fff;
  background-image: linear-gradient(
    to top,
    rgba(0, 0, 0, 0) 0%,
    rgba(0, 0, 0, 0.7) 100%
  );
  opacity: 0;
  transition: all 0.2s ease-in-out;
}
.__UIV_SCOPE__ .card:hover .card_form span,
.__UIV_SCOPE__ .card:hover .card_data span {
  opacity: 1;
}
.__UIV_SCOPE__ .card_data {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.__UIV_SCOPE__ .card_data span {
  color: #9147ff;
  display: flex;
  align-items: center;
  font-size: 0.9em;
  transition: 0.2s ease-in-out;
  opacity: 0;
  cursor: pointer;
}
.__UIV_SCOPE__ .card_data span:hover {
  text-decoration: underline;
}
.__UIV_SCOPE__ .text {
  display: flex;
  justify-content: center;
  flex-direction: column;
  color: white;
}
.__UIV_SCOPE__ .text_m {
  font-size: 0.9em;
}
.__UIV_SCOPE__ .text_s {
  color: #9147ff;
  font-size: 0.6em;
}
.__UIV_SCOPE__ .cube {
  width: max-content;
  height: 10px;
  transition: all 0.2s;
  transform-style: preserve-3d;
}
.__UIV_SCOPE__ .card:hover .cube {
  transform: rotateX(90deg);
}
.__UIV_SCOPE__ .side {
  width: max-content;
  height: 1em;
  display: flex;
  justify-content: center;
  align-items: center;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  font-weight: bold;
}
.__UIV_SCOPE__ .top {
  transform: rotateX(-90deg) translate3d(0, 0, 0em);
}
.__UIV_SCOPE__ .front {
  transform: translate3d(0, 0, 1em);
}
